-- migrate:up
set lock_timeout = '5s';
create schema app;
grant usage on schema app to app_user, app_system;

-- Konteks tenant dibaca dari setting transaksi. Kosong -> null -> nol baris.
create function app.current_org() returns uuid language sql stable as
$$ select nullif(current_setting('app.org_id', true), '')::uuid $$;
create function app.current_user_id() returns text language sql stable as
$$ select nullif(current_setting('app.user_id', true), '') $$;

create table plans (
  id text primary key,
  max_staff int not null,
  max_bookings_per_month int not null,
  price_idr int not null
);
insert into plans values ('gratis', 2, 100, 0), ('pro', 20, 5000, 299000);

create table orgs (
  id uuid primary key default gen_random_uuid(),
  name text not null check (length(name) between 2 and 80),
  plan_id text not null default 'gratis' references plans,
  paid_until timestamptz,
  created_at timestamptz not null default now()
);

create table memberships (
  org_id uuid not null references orgs on delete cascade,
  user_id text not null, -- id user dari Better Auth
  role text not null check (role in ('owner', 'admin', 'member')),
  created_at timestamptz not null default now(),
  primary key (org_id, user_id)
);
create index on memberships (user_id);

create table invites (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs on delete cascade,
  email text not null,
  role text not null check (role in ('admin', 'member')),
  token_hash bytea not null unique, -- sha256 token; token mentah tidak pernah disimpan
  expires_at timestamptz not null,
  accepted_at timestamptz,
  created_by text not null
);
create index on invites (org_id);

create table bookings (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references orgs on delete cascade,
  client_name text not null,
  client_email text not null,
  starts_at timestamptz not null,
  status text not null default 'confirmed' check (status in ('confirmed', 'cancelled')),
  created_at timestamptz not null default now()
);
create index on bookings (org_id, starts_at);

create table audit_log (
  id bigint generated always as identity primary key,
  org_id uuid not null references orgs on delete cascade,
  actor_id text not null,
  action text not null,
  target text,
  meta jsonb not null default '{}',
  at timestamptz not null default now()
);
create index on audit_log (org_id, at desc);

create table feature_flags (
  key text not null,
  org_id uuid references orgs on delete cascade, -- null = nilai bawaan semua tenant
  enabled boolean not null,
  unique nulls not distinct (key, org_id)
);

create table rate_limits (
  org_id uuid not null references orgs on delete cascade,
  bucket text not null,
  window_start timestamptz not null,
  hits int not null,
  primary key (org_id, bucket, window_start)
);

create table billing_orders (
  order_id text primary key,
  org_id uuid not null references orgs on delete cascade,
  plan_id text not null references plans,
  gross_amount numeric(12, 2) not null,
  status text not null default 'pending' check (status in ('pending', 'paid', 'failed')),
  paid_at timestamptz
);
create index on billing_orders (org_id);

create table webhook_events (
  provider text not null,
  event_key text not null,
  payload jsonb not null,
  received_at timestamptz not null default now(),
  primary key (provider, event_key)
);

create table jobs (
  id bigint generated always as identity primary key,
  org_id uuid references orgs on delete cascade,
  kind text not null,
  payload jsonb not null,
  dedupe_key text unique,
  run_at timestamptz not null default now(),
  attempts int not null default 0,
  max_attempts int not null default 5,
  locked_until timestamptz,
  last_error text,
  done_at timestamptz
);
create index jobs_ready on jobs (run_at) where done_at is null;
create index on jobs (org_id);

-- RLS: app_user hanya melihat baris tenant aktif; app_system punya policy eksplisit.
do $$
declare t text;
begin
  foreach t in array array['memberships', 'invites', 'bookings', 'audit_log',
                           'rate_limits', 'billing_orders', 'jobs'] loop
    execute format('alter table %I enable row level security', t);
    execute format('create policy tenant on %I to app_user
                      using (org_id = app.current_org())
                      with check (org_id = app.current_org())', t);
    execute format('create policy system on %I to app_system using (true) with check (true)', t);
  end loop;
end $$;

-- Daftar organisasi milik user (untuk pemilih organisasi), sebelum tenant dipilih.
create policy own_rows on memberships for select to app_user
  using (user_id = app.current_user_id());

alter table orgs enable row level security;
create policy tenant on orgs for select to app_user using (
  id = app.current_org()
  or exists (select 1 from memberships m where m.org_id = orgs.id and m.user_id = app.current_user_id()));
create policy tenant_update on orgs for update to app_user
  using (id = app.current_org()) with check (id = app.current_org());
create policy system on orgs to app_system using (true) with check (true);

alter table feature_flags enable row level security;
create policy tenant on feature_flags for select to app_user
  using (org_id is null or org_id = app.current_org());
create policy system on feature_flags to app_system using (true) with check (true);

-- Hak minimum. audit_log append-only bagi aplikasi: tanpa update/delete.
grant select on plans to app_user, app_system;
grant select, update (name) on orgs to app_user;
grant select, insert, update, delete on memberships, invites, bookings to app_user;
grant select, insert on audit_log to app_user;
grant select, insert, update on rate_limits to app_user;
grant select on billing_orders, feature_flags to app_user;
grant insert, select (dedupe_key) on jobs to app_user; -- select kolom untuk ON CONFLICT
grant select, insert, update, delete on all tables in schema public to app_system;

-- Batas paket ditegakkan di database: kunci baris org agar dua insert paralel tidak lolos bersamaan.
create function app.enforce_booking_limit() returns trigger
language plpgsql security definer set search_path = public, app as $$
declare lim int; used int;
begin
  select p.max_bookings_per_month into lim
    from orgs o join plans p on p.id = o.plan_id
   where o.id = new.org_id for update of o;
  select count(*) into used from bookings
   where org_id = new.org_id and created_at >= date_trunc('month', now());
  if used >= lim then
    raise exception 'plan_limit:bookings' using errcode = 'P0001';
  end if;
  return new;
end $$;
create trigger booking_limit before insert on bookings
  for each row execute function app.enforce_booking_limit();

-- Dua pintu sempit tanpa konteks tenant: buat org baru dan terima undangan.
create function app.create_org(p_name text, p_user text) returns uuid
language plpgsql security definer set search_path = public, app as $$
declare new_id uuid;
begin
  insert into orgs (name) values (p_name) returning id into new_id;
  insert into memberships (org_id, user_id, role) values (new_id, p_user, 'owner');
  insert into audit_log (org_id, actor_id, action) values (new_id, p_user, 'org.created');
  return new_id;
end $$;

create function app.accept_invite(p_hash bytea, p_user text, p_email text) returns uuid
language plpgsql security definer set search_path = public, app as $$
declare inv invites;
begin
  update invites set accepted_at = now()
   where token_hash = p_hash and accepted_at is null and expires_at > now()
     and lower(email) = lower(p_email)
  returning * into inv;
  if not found then
    raise exception 'invite_invalid' using errcode = 'P0001';
  end if;
  insert into memberships (org_id, user_id, role) values (inv.org_id, p_user, inv.role)
    on conflict (org_id, user_id) do nothing;
  insert into audit_log (org_id, actor_id, action, target)
    values (inv.org_id, p_user, 'invite.accepted', inv.email);
  return inv.org_id;
end $$;

revoke execute on all functions in schema app from public;
grant execute on function app.current_org(), app.current_user_id() to app_user, app_system;
grant execute on function app.create_org(text, text), app.accept_invite(bytea, text, text) to app_user;

-- migrate:down
drop schema app cascade;
drop table jobs, webhook_events, billing_orders, rate_limits, feature_flags,
  audit_log, bookings, invites, memberships, orgs, plans;

