import postgres from "postgres";

// Dua koneksi, dua role. Kode request web HANYA boleh memakai sqlUser.
export const sqlUser = postgres(process.env.DATABASE_URL_APP!, { max: 10 });
export const sqlSystem = postgres(process.env.DATABASE_URL_SYSTEM!, { max: 3 });

export type Role = "owner" | "admin" | "member";
export type Tx = postgres.TransactionSql;

export class Forbidden extends Error {
  status = 403;
}

// Satu transaksi = satu tenant. set_config(..., true) hanya berlaku sampai
// transaksi selesai, jadi aman dipakai lewat pooler mode transaksi.
export async function withTenant<T>(
  userId: string,
  orgId: string,
  fn: (tx: Tx, role: Role) => Promise<T>,
): Promise<T> {
  return sqlUser.begin(async (tx) => {
    await tx`select set_config('app.user_id', ${userId}, true)`;
    const [m] = await tx<{ role: Role }[]>`
      select role from memberships where org_id = ${orgId} and user_id = ${userId}`;
    if (!m) throw new Forbidden("Kamu bukan anggota organisasi ini.");
    await tx`select set_config('app.org_id', ${orgId}, true)`;
    return fn(tx, m.role);
  }) as Promise<T>;
}

export async function audit(tx: Tx, actorId: string, action: string, target?: string, meta: Record<string, unknown> = {}) {
  await tx`
    insert into audit_log (org_id, actor_id, action, target, meta)
    values (app.current_org(), ${actorId}, ${action}, ${target ?? null}, ${tx.json(meta as postgres.JSONValue)})`;
}

import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import { randomUUID } from "node:crypto";
import { sqlUser, sqlSystem, withTenant, Forbidden } from "#lib/db.ts";

const A = randomUUID();
const B = randomUUID();

before(async () => {
  await sqlSystem`insert into orgs (id, name) values (${A}, 'Klinik A'), (${B}, 'Salon B')`;
  await sqlSystem`insert into memberships (org_id, user_id, role)
    values (${A}, 'alice', 'owner'), (${B}, 'bob', 'owner')`;
  await sqlSystem`insert into bookings (org_id, client_name, client_email, starts_at) values
    (${A}, 'Pasien A', 'a@contoh.id', now() + interval '1 day'),
    (${B}, 'Pelanggan B', 'b@contoh.id', now() + interval '1 day')`;
});

after(async () => {
  await sqlSystem`delete from orgs where id in (${A}, ${B})`;
  await Promise.all([sqlUser.end(), sqlSystem.end()]);
});

test("anggota A hanya melihat booking A", async () => {
  const rows = await withTenant("alice", A, (tx) => tx`select org_id from bookings`);
  assert.ok(rows.length > 0);
  assert.ok(rows.every((r) => r.org_id === A));
});

test("filter org_id B dari dalam tenant A tetap nol baris", async () => {
  const rows = await withTenant("alice", A, (tx) => tx`select * from bookings where org_id = ${B}`);
  assert.equal(rows.length, 0);
});

test("bukan anggota tidak bisa masuk tenant B", async () => {
  await assert.rejects(withTenant("alice", B, async () => 1), Forbidden);
});

test("menulis baris untuk tenant lain ditolak RLS", async () => {
  await assert.rejects(
    withTenant("alice", A, (tx) => tx`
      insert into bookings (org_id, client_name, client_email, starts_at)
      values (${B}, 'Penyusup', 'x@contoh.id', now())`),
    /row-level security/,
  );
});

test("update dan delete lintas tenant tidak mengenai baris apa pun", async () => {
  const n = await withTenant("alice", A, async (tx) => {
    const u = await tx`update bookings set status = 'cancelled' where org_id = ${B}`;
    const d = await tx`delete from bookings where org_id = ${B}`;
    return u.count + d.count;
  });
  assert.equal(n, 0);
});

test("tanpa konteks tenant, app_user tidak melihat apa pun", async () => {
  const [r] = await sqlUser`select count(*)::int as n from bookings`;
  assert.equal(r.n, 0);
});

test("setelah transaksi tenant selesai, konteksnya kosong lagi", async () => {
  await withTenant("alice", A, async () => 1);
  const [r] = await sqlUser`select app.current_org() as org`;
  assert.equal(r.org, null);
});

test("audit log tidak bisa diubah oleh aplikasi", async () => {
  await assert.rejects(
    withTenant("alice", A, (tx) => tx`delete from audit_log`),
    /permission denied/,
  );
});

import { betterAuth } from "better-auth";
import { Pool } from "pg";
import { sendMail } from "./mail.ts";

// Better Auth memakai role DB-nya sendiri (app_auth) dan tabelnya sendiri (user, session, account, verification).
// Role app_user TIDAK diberi akses ke tabel-tabel itu.
export const auth = betterAuth({
  database: new Pool({ connectionString: process.env.DATABASE_URL_AUTH }),
  emailAndPassword: { enabled: true, requireEmailVerification: true, minPasswordLength: 12 },
  emailVerification: {
    sendOnSignUp: true,
    sendVerificationEmail: async ({ user, url }) => {
      await sendMail(user.email, "Verifikasi email akunmu", `Buka tautan ini untuk verifikasi: ${url}`);
    },
  },
  rateLimit: { enabled: true },
});

// Kirim email lewat API Resend. idempotencyKey membuat percobaan ulang tidak menghasilkan email dobel.
export async function sendMail(to: string, subject: string, text: string, idempotencyKey?: string) {
  const res = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${process.env.RESEND_API_KEY}`,
      "Content-Type": "application/json",
      ...(idempotencyKey ? { "Idempotency-Key": idempotencyKey } : {}),
    },
    body: JSON.stringify({ from: process.env.MAIL_FROM, to, subject, text }),
  });
  if (!res.ok) throw new Error(`resend ${res.status}: ${await res.text()}`);
}

import { createHash, randomBytes } from "node:crypto";
import { sqlUser, audit, Forbidden, type Role, type Tx } from "./db.ts";

const rank: Record<Role, number> = { member: 0, admin: 1, owner: 2 };

// owner boleh mengundang/mengubah admin dan member; admin hanya member; member tidak apa pun.
export function canManage(actor: Role, target: Role): boolean {
  return actor !== "member" && rank[actor] > rank[target];
}

export const hashToken = (token: string) => createHash("sha256").update(token).digest();

export async function createOrg(userId: string, name: string): Promise<string> {
  const [r] = await sqlUser`select app.create_org(${name}, ${userId}) as id`;
  return r.id;
}

// Mengembalikan token mentah SATU KALI untuk dikirim lewat email. Di DB hanya hash-nya.
export async function createInvite(tx: Tx, actor: { id: string; role: Role }, email: string, role: "admin" | "member") {
  if (!canManage(actor.role, role)) throw new Forbidden(`Role ${actor.role} tidak boleh mengundang ${role}.`);
  const token = randomBytes(32).toString("base64url");
  await tx`
    insert into invites (org_id, email, role, token_hash, expires_at, created_by)
    values (app.current_org(), ${email.trim().toLowerCase()}, ${role}, ${hashToken(token)},
            now() + interval '7 days', ${actor.id})`;
  await audit(tx, actor.id, "invite.created", email, { role });
  return token;
}

// Email harus email yang SUDAH terverifikasi di sesi auth, bukan dari form.
export async function acceptInvite(userId: string, verifiedEmail: string, token: string): Promise<string> {
  const [r] = await sqlUser`select app.accept_invite(${hashToken(token)}, ${userId}, ${verifiedEmail}) as org_id`;
  return r.org_id;
}

import { test, after } from "node:test";
import assert from "node:assert/strict";
import { sqlUser, sqlSystem, withTenant, Forbidden } from "#lib/db.ts";
import { canManage, createOrg, createInvite, acceptInvite } from "#lib/org.ts";

const made: string[] = [];
after(async () => {
  await sqlSystem`delete from orgs where id = any(${made})`;
  await Promise.all([sqlUser.end(), sqlSystem.end()]);
});

test("matriks role", () => {
  assert.equal(canManage("owner", "admin"), true);
  assert.equal(canManage("admin", "member"), true);
  assert.equal(canManage("admin", "admin"), false);
  assert.equal(canManage("member", "member"), false);
});

test("undangan: sekali pakai, terikat email", async () => {
  const org = await createOrg("owner-1", "Klinik Sehat");
  made.push(org);
  const token = await withTenant("owner-1", org, (tx, role) =>
    createInvite(tx, { id: "owner-1", role }, "Staf@Contoh.id", "member"));

  await assert.rejects(acceptInvite("orang-lain", "lain@contoh.id", token), /invite_invalid/);
  assert.equal(await acceptInvite("staf-1", "staf@contoh.id", token), org);
  await assert.rejects(acceptInvite("staf-1", "staf@contoh.id", token), /invite_invalid/);

  const role = await withTenant("staf-1", org, async (_tx, r) => r);
  assert.equal(role, "member");
  await assert.rejects(
    withTenant("staf-1", org, (tx, r) => createInvite(tx, { id: "staf-1", role: r }, "x@contoh.id", "member")),
    Forbidden,
  );
});

test("batas paket gratis menolak booking ke-101 bulan ini", async () => {
  const org = await createOrg("owner-2", "Salon Kecil");
  made.push(org);
  await sqlSystem`insert into bookings (org_id, client_name, client_email, starts_at)
    select ${org}, 'P' || g, 'p@contoh.id', now() from generate_series(1, 100) g`;
  await assert.rejects(
    withTenant("owner-2", org, (tx) => tx`
      insert into bookings (org_id, client_name, client_email, starts_at)
      values (${org}, 'Ke-101', 'p@contoh.id', now())`),
    /plan_limit:bookings/,
  );
});

import { createHash, timingSafeEqual } from "node:crypto";
import { sqlSystem } from "./db.ts";

const API = process.env.MIDTRANS_API_BASE ?? "https://api.sandbox.midtrans.com";
const serverKey = () => process.env.MIDTRANS_SERVER_KEY!;

export type Notification = {
  order_id: string;
  status_code: string;
  gross_amount: string;
  signature_key: string;
  transaction_status: string;
  fraud_status?: string;
};

// signature_key = SHA512(order_id + status_code + gross_amount + ServerKey)
export function validSignature(n: Partial<Notification>, key = serverKey()): boolean {
  if (!n.order_id || !n.status_code || !n.gross_amount || !n.signature_key) return false;
  const expected = createHash("sha512")
    .update(n.order_id + n.status_code + n.gross_amount + key)
    .digest("hex");
  const got = Buffer.from(n.signature_key);
  return got.length === expected.length && timingSafeEqual(got, Buffer.from(expected));
}

// Isi notifikasi hanya pemicu. Status yang dipercaya diambil ulang dari API Midtrans.
export async function fetchStatus(orderId: string): Promise<Notification> {
  const res = await fetch(`${API}/v2/${encodeURIComponent(orderId)}/status`, {
    headers: {
      Accept: "application/json",
      Authorization: "Basic " + Buffer.from(serverKey() + ":").toString("base64"),
    },
  });
  if (!res.ok) throw new Error(`midtrans status ${res.status}`);
  return res.json() as Promise<Notification>;
}

const FAILED = new Set(["deny", "cancel", "expire", "failure"]);

// Idempoten: (order_id, status) dicatat sekali; order hanya pindah pending -> paid/failed sekali.
export async function applyPayment(s: Notification, raw: unknown): Promise<"duplikat" | "dibayar" | "gagal" | "diabaikan"> {
  const paid = s.transaction_status === "settlement" ||
    (s.transaction_status === "capture" && s.fraud_status === "accept");

  return sqlSystem.begin(async (tx) => {
    const fresh = await tx`
      insert into webhook_events (provider, event_key, payload)
      values ('midtrans', ${`${s.order_id}:${s.transaction_status}`}, ${tx.json(raw as never)})
      on conflict do nothing returning 1`;
    if (fresh.length === 0) return "duplikat";

    if (FAILED.has(s.transaction_status)) {
      await tx`update billing_orders set status = 'failed'
               where order_id = ${s.order_id} and status = 'pending'`;
      return "gagal";
    }
    if (!paid) return "diabaikan"; // pending, refund, dsb: tangani sesuai kebijakanmu

    const [o] = await tx`
      update billing_orders set status = 'paid', paid_at = now()
      where order_id = ${s.order_id} and status <> 'paid' and gross_amount = ${s.gross_amount}
      returning org_id, plan_id`;
    if (!o) return "diabaikan"; // sudah dibayar, order tak dikenal, atau nominal tidak cocok

    await tx`
      update orgs set plan_id = ${o.plan_id},
        paid_until = greatest(coalesce(paid_until, now()), now()) + interval '1 month'
      where id = ${o.org_id}`;
    await tx`
      insert into audit_log (org_id, actor_id, action, target, meta)
      values (${o.org_id}, 'system:midtrans', 'billing.paid', ${s.order_id}, ${tx.json({ plan: o.plan_id })})`;
    return "dibayar";
  }) as Promise<"duplikat" | "dibayar" | "gagal" | "diabaikan">;
}

import { validSignature, fetchStatus, applyPayment, type Notification } from "#lib/midtrans.ts";
import { log } from "#lib/log.ts";

export async function POST(req: Request) {
  let n: Partial<Notification>;
  try {
    n = await req.json();
  } catch {
    return new Response("bad json", { status: 400 });
  }
  if (!validSignature(n)) {
    log.warn({ order_id: n.order_id }, "midtrans: tanda tangan salah");
    return new Response("bad signature", { status: 401 });
  }
  try {
    const status = await fetchStatus(n.order_id!);
    const result = await applyPayment(status, n);
    log.info({ order_id: n.order_id, status: status.transaction_status, result }, "midtrans: diproses");
    return new Response("ok");
  } catch (err) {
    // Non-2xx membuat Midtrans mengirim ulang nanti; aman karena applyPayment idempoten.
    log.error({ err, order_id: n.order_id }, "midtrans: gagal diproses");
    return new Response("retry", { status: 500 });
  }
}

import { test, before, after } from "node:test";
import assert from "node:assert/strict";
import { createHash, randomUUID } from "node:crypto";
import { sqlSystem } from "#lib/db.ts";
import { POST } from "../app/api/webhooks/midtrans/route.ts";

process.env.MIDTRANS_SERVER_KEY = "SB-Mid-server-uji";
const org = randomUUID();
const orderId = `sub-${org.slice(0, 8)}-202611`;

function notif(status: string, gross = "299000.00") {
  const sig = createHash("sha512").update(orderId + "200" + gross + process.env.MIDTRANS_SERVER_KEY).digest("hex");
  return { order_id: orderId, status_code: "200", gross_amount: gross, signature_key: sig, transaction_status: status };
}
const call = (body: unknown) =>
  POST(new Request("http://x/api/webhooks/midtrans", { method: "POST", body: JSON.stringify(body) }));

let apiStatus = "settlement";
before(async () => {
  globalThis.fetch = (async () => Response.json(notif(apiStatus))) as typeof fetch;
