// kalau transaksi batal, job-nya ikut batal (tidak ada email untuk booking yang gagal dibuat).
export async function enqueue(
  tx: Tx,
  kind: string,
  payload: Record<string, unknown>,
  opts: { runAt?: Date; dedupeKey?: string } = {},
) {
  await tx`
    insert into jobs (org_id, kind, payload, run_at, dedupe_key)
    values (app.current_org(), ${kind}, ${tx.json(payload as never)},
            ${opts.runAt ?? new Date()}, ${opts.dedupeKey ?? null})
    on conflict (dedupe_key) do nothing`;
}

