export type Job = { id: number; org_id: string | null; kind: string; payload: any; attempts: number; max_attempts: number };
export type Handler = (payload: any, job: Job) => Promise<void>;

// Ambil satu job siap jalan. SKIP LOCKED: beberapa worker paralel tidak saling menunggu
// dan tidak mengambil job yang sama. locked_until menyelamatkan job jika worker mati di tengah.
export async function runOnce(handlers: Record<string, Handler>): Promise<boolean> {
  const [job] = await sql<Job[]>`
    update jobs set attempts = attempts + 1, locked_until = now() + interval '5 minutes'
    where id = (
      select id from jobs
      where done_at is null and run_at <= now() and attempts < max_attempts
        and (locked_until is null or locked_until < now())
      order by run_at
      limit 1
      for update skip locked)
    returning id, org_id, kind, payload, attempts, max_attempts`;
  if (!job) return false;

  const jlog = log.child({ job_id: job.id, kind: job.kind, org_id: job.org_id, attempt: job.attempts });
  try {
    const handler = handlers[job.kind];
    if (!handler) throw new Error(`tidak ada handler untuk ${job.kind}`);
    await handler(job.payload, job);
    await sql`update jobs set done_at = now(), locked_until = null, last_error = null where id = ${job.id}`;
    jlog.info("job selesai");
  } catch (err) {
    // Backoff eksponensial: 1, 2, 4, 8 ... menit, maksimal 1 jam.
    const delaySec = Math.min(30 * 2 ** job.attempts, 3600);
    await sql`
      update jobs set locked_until = null, last_error = ${String(err)},
        run_at = now() + make_interval(secs => ${delaySec})
      where id = ${job.id}`;
    const dead = job.attempts >= job.max_attempts;
    jlog[dead ? "error" : "warn"]({ err }, dead ? "job menyerah, perlu dicek manual" : "job gagal, akan dicoba lagi");
  }
  return true;
}

