export class TooManyRequests extends Error {
  status = 429;
}

// Jendela tetap per tenant per bucket. Panggil di transaksi TERSENDIRI sebelum
// transaksi utama, supaya hitungan tidak ikut batal saat request gagal.
// ponytail: fixed window di Postgres; pindah ke Redis/Upstash kalau tabel ini jadi panas.
export async function rateLimit(tx: Tx, bucket: string, limit: number, windowSec = 60) {
  const [r] = await tx<{ hits: number }[]>`
    insert into rate_limits (org_id, bucket, window_start, hits)
    values (app.current_org(), ${bucket},
            to_timestamp(floor(extract(epoch from now()) / ${windowSec}) * ${windowSec}), 1)
    on conflict (org_id, bucket, window_start)
      do update set hits = rate_limits.hits + 1
    returning hits`;
  if (r.hits > limit) throw new TooManyRequests(`Batas ${limit} request per ${windowSec} detik tercapai.`);
}

// Nilai khusus tenant menang atas nilai bawaan (org_id null). Tidak ada baris = mati.
export async function flag(tx: Tx, key: string): Promise<boolean> {
  const [r] = await tx<{ enabled: boolean }[]>`
    select enabled from feature_flags
    where key = ${key} and (org_id = app.current_org() or org_id is null)
    order by org_id nulls last
    limit 1`;
  return r?.enabled ?? false;
}

