import { headers } from "next/headers";
import * as Sentry from "@sentry/nextjs";
import { randomUUID } from "node:crypto";
import { auth } from "./auth.ts";
import { withTenant, type Role, type Tx } from "./db.ts";
import { rateLimit } from "./guard.ts";
import { ctx, log } from "./log.ts";

type Me = { id: string; email: string; role: Role };
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

// Satu pintu untuk semua route tenant: sesi -> konteks log -> rate limit -> RLS -> peta error.
export async function tenantAction<T>(orgId: string, fn: (tx: Tx, me: Me) => Promise<T>): Promise<Response> {
  if (!UUID.test(orgId)) return Response.json({ error: "Tidak ditemukan." }, { status: 404 });
  const session = await auth.api.getSession({ headers: await headers() });
  if (!session) return Response.json({ error: "Belum masuk." }, { status: 401 });
  const { id, email } = session.user;

  return ctx.run({ req_id: randomUUID(), org_id: orgId, user_id: id }, async () => {
    Sentry.setTag("org_id", orgId);
    try {
      await withTenant(id, orgId, (tx) => rateLimit(tx, "api", 300)); // transaksi terpisah
      const data = await withTenant(id, orgId, (tx, role) => fn(tx, { id, email, role }));
      return Response.json(data);
    } catch (err: any) {
      if (err?.status === 400 || err?.status === 403 || err?.status === 429) {
        return Response.json({ error: err.message }, { status: err.status });
      }
      if (err?.code === "P0001" && String(err.message).startsWith("plan_limit:")) {
        return Response.json({ error: "Batas paketmu tercapai. Naikkan paket untuk lanjut.", code: err.message }, { status: 402 });
      }
      log.error({ err }, "request gagal");
      Sentry.captureException(err);
      return Response.json({ error: "Terjadi kesalahan. Coba lagi sebentar." }, { status: 500 });
    }
  });
}

import { tenantAction } from "#lib/tenant-action.ts";
import { audit } from "#lib/db.ts";
import { enqueue } from "#lib/jobs.ts";

type Ctx = { params: Promise<{ orgId: string }> };

export async function GET(_req: Request, { params }: Ctx) {
  const { orgId } = await params;
  // Tidak ada "where org_id = ..." di sini: RLS yang menyaring. Filter manual boleh, tapi bukan pengaman.
  return tenantAction(orgId, (tx) => tx`
    select id, client_name, starts_at, status from bookings
    where starts_at >= now() order by starts_at limit 100`);
}

export async function POST(req: Request, { params }: Ctx) {
  const { orgId } = await params;
  const body = await req.json().catch(() => null);
  return tenantAction(orgId, async (tx, me) => {
    const startsAt = new Date(body?.starts_at);
    if (!body?.client_name || !/^\S+@\S+\.\S+$/.test(body?.client_email ?? "") || isNaN(+startsAt)) {
      throw Object.assign(new Error("Data booking tidak lengkap."), { status: 400 });
    }
    const [b] = await tx`
      insert into bookings (org_id, client_name, client_email, starts_at)
      values (app.current_org(), ${body.client_name}, ${body.client_email}, ${startsAt})
      returning id, starts_at`;
    await enqueue(tx, "booking.reminder", { booking_id: b.id }, {
      runAt: new Date(startsAt.getTime() - 24 * 3600 * 1000),
      dedupeKey: `reminder:${b.id}`,
    });
    await audit(tx, me.id, "booking.created", b.id);
    return b;
  });
}

